INSERT INTO step1_ideas (idea_id,name,description,category,parent_idea_id,status,kill_gate,kill_reason,killed_at,created_at,updated_at,idea_kind,output_type) VALUES ('BRC-001','BRC — Break-Retest-Continuation (structural breakout/pullback continuation)','Break of Two Barriers: two consecutive same-direction swing breakouts mark an institutional imbalance zone; L1 (1st-break swing) = retest entry, L2 (extreme swing) = invalidation, 50%% = zone centre. Multi-TF confluence (up to 9 TFs) + russian-doll fractal nesting. Edge = mean-reversion retest of broken structure conditioned on 2-breakout setup. BUILD FRESH on STRUCT-001 primitive (NOT b2b/sigma_core). Academic validation prior-art queued (call_id 69).','strategy','STRUCT-001','gate_2',NULL,NULL,NULL,'2026-06-15 20:24:24','2026-06-17 14:01:50','strategy','pnl_stream');
INSERT INTO step3_gates (gate_id,idea_id,gate_number,attempt,gate_question,gate_answer,pass_criteria,status,answered_by,created_at,updated_at,answered_at) VALUES (31,'BRC-001',0,1,'Do we know the model''s mathematical truth from the literature?','YES — 3 dissected keepers (call_ids 70/71/72) supply the math:
INSERT INTO step3_gates (gate_id,idea_id,gate_number,attempt,gate_question,gate_answer,pass_criteria,status,answered_by,created_at,updated_at,answered_at) VALUES (32,'BRC-001',1,1,'What is the simple human-readable rule and null hypothesis?','RULE (human-readable): After TWO consecutive same-direction swing breakouts (B2B = institutional imbalance), wait for price to pull back and RETEST the broken zone; enter IN THE BREAK DIRECTION when the retest holds (continuation-after-pullback). Stop beyond the zone; first target = next structure.
INSERT INTO step3_gates (gate_id,idea_id,gate_number,attempt,gate_question,gate_answer,pass_criteria,status,answered_by,created_at,updated_at,answered_at) VALUES (33,'BRC-001',2,1,'Does the simplest possible implementation produce sane output?','PASS. 500-bar D1 3-way sanity render (overview_buy 23 / sell 13 / both 36 zones). Syafiq eyeballed all three 2026-06-17: BUY boxes at price dips, SELL boxes at price peaks, both==buy+sell reconciles. Spurious cross-structure zones killed by task-113 freshness gate. Detection diverges from EA by design (Path B) -> validation = eyeball (done) + Gate-3 edge test (task 110).','Path-B detector renders structurally sane zones on D1: BUY at swing-low pullbacks, SELL at swing-high tops, counts reconcile (both==buy+sell), no spurious bridge zones. Syafiq eyeball of 3-way overview (buy/sell/both).','passed','human','2026-06-17 14:01:50','2026-06-17 14:01:50','2026-06-17 14:01:50');
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (46,'BRC-001','spec birth','config',NULL,'continuation-retest (enter in break direction on zone retest)','CREATED','Lit synthesis (Osler/Chung/Costa) reframes gold B2B as continuation-after-pullback; Costa''s 66.78% gold confirm flips the FX fade default. H_base=continuation, H_alt=fade.',NULL,NULL,'human','2026-06-16 11:35:50','{"entry": "retest-hold in break direction", "trigger": "2x same-dir swing breakout", "stop": "beyond zone", "null_H_base": "continuation E[R]<=0 net", "H_alt": "fade-the-level", "chung_knobs": ["min_touch", "age_cutoff"]}');
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (47,'BRC-001','CREATED','entry','stub (NotImplementedError)','minimal-core 5-pointer detect_zones() (P1->P2->P3->P5 + P4 close-confirm + L1=P2/L2=extreme)','CREATED','Task 107. Faithful port of B2BDetector.mqh / b2b_engine.py Pass-1 MINUS the 4 filters (no-interruption, early-fade, freshest-per-P5, swing-dedup) which are the locked variants. P3 has NO price gate (EA-faithful; P3>=P1 absorbed by L2=extreme). P4=plain first-close-beyond-P5 (EA rule), NOT struct.rawbreakout. D1: 1254 zones (564 sell/690 buy), 0/1254 geometry-invariant violations.',NULL,'e618761','human','2026-06-17 06:51:59','{"tf": "D1", "swing_window": 3, "filters_deferred": ["no_interruption", "early_fade", "freshest_per_p5", "swing_dedup"]}');
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (48,'BRC-001','detection_method_locked','entry','swing-scan + close-scan P4 (EA-style, current zones.py)','rawbreakout-derived: pair same-dir struct rawbreakouts (P2 then P5) + swings for P1/P3','ADOPTED','Path B makes H_alt-2 (is 2nd break load-bearing) measurable for the Gate-3 edge test; single breakout source-of-truth (struct, parity-tested); look-ahead hardened. Cost: loses EA zone-for-zone parity. L1=P2, L2=P1 (P3<P1 gate restored).',NULL,NULL,'human','2026-06-17 08:06:19','{"L1": "P2", "L2": "P1", "gate": "P3<P1 enforced", "p4": "same-bar OR sequential P2+P5 break", "validation": "eyeball Gate2 + edge test (EA no longer oracle)"}');
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (49,'BRC-001','CREATED','management','none (zones never died post-P4)','zone invalidation: CLOSE beyond L2 = DEAD (close>max(L1,L2) SELL / close<min(L1,L2) BUY, EA-mirrored)','ADOPTED','task 116 lifecycle.py — death boundary every later measurement (retest ladder + continuation horizon, task 108) must respect. T3 wick-poke of L2 keeps zone alive; only a CLOSE beyond L2 kills it. Verified first-death invariant 0/196 violations on D1 full history (196 dead, 49 alive, median 20 bars).',NULL,NULL,'human','2026-06-17 14:10:06',NULL);
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (50,'BRC-001','CREATED','entry','none (zone geometry only, no trigger)','retest ladder entry (wick touch T1/T2/mid/T3) + Option-A continuation label from touch bar','PROPOSED','task 108 — per-zone dataset for Gate-3 edge test (task 110). H_base=continuation>0 vs H_alt-1=fade; deepest_T + break_kind (same_bar/sequential=H_alt-2) as conditioners. Raw price points, no cost — cost+significance applied at Gate 3. Not yet validated.',NULL,NULL,'human','2026-06-17 14:16:20',NULL);
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (51,'BRC-001','FALSIFIED','entry','retest predicts continuation direction (H_base)','no directional edge over trend beta','FALSIFIED','D1 conditioner (cost-free, Ruler-B 1R close-based race, entry=L1 retest). Pooled win=50.5%; by dir BUY 56.5%/SELL 44.2%. Trend-beta baseline (random same-dir entry, same per-zone R, ±1R, 2000-boot): BUY base 57.7+/-4.8 (BRC z=-0.25), SELL base 41.9+/-4.7 (BRC z=+0.51). Retest entry adds nothing over beta. SURVIVING hypothesis: payoff/exit asymmetry (winners MFE~2R vs 1R stop) untested vs let-winners-run baseline -> NOT a kill (needs 2nd falsified + that test).',NULL,NULL,'human','2026-06-17 15:22:10',NULL);
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (52,'BRC-001','FALSIFIED','exit','let-winners-run hold (stop=L2, no TP) from L1 retest','no payoff edge over trend beta','FALSIFIED','Payoff-asymmetry test (handover Next#1): unmanaged let-run-to-invalidation from the L1 retest vs MATCHED random same-dir baseline (paired R + direction, uniform entry, 2000-boot), D1 cost-free. BRC E[R]=+13.67R vs beta +12.74+-4.65 (z=+0.20, pct 63.6%); win% 14.0 vs 12.3 (z=+0.84); median -1.26R. The +28.6R BUY mean is pure 2016-2026 bull-run runner tail the matched same-dir baseline reproduces. 2nd FALSIFIED after the symmetric 1R race (#51) => BRC killable (rule 8b).',NULL,'5017660','agent','2026-06-17 15:32:48',NULL);
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (53,'BRC-001','FALSIFIED','exit','H4 reframe of let-winners-run payoff (Syafiq: reframe not kill)','cap-dependent outlier mirage — not a robust edge over beta','FALSIFIED','H4 let-run-to-invalidation vs matched same-dir baseline (paired R+dir, 2000-boot). UNCAPPED E[R]=+29.65R z=+3.50 looked like an edge BUT is an outlier artifact: top-1 trade=4832R, top-10 trades=60pct of total sum — tiny-R zones that never invalidate normalize a multi-year hold to thousands of R. Winsorizing realized R identically on BRC+baseline collapses it: cap=10R z+2.31 but E[R]=-1.15R (still LOSES), cap=20R z+1.80, cap=50R z+1.02. win% +1.76 throughout. No tradeable edge clears Gate-5 (z>=2) at any positive-EV cap. D1 flat (z+0.21). Reframe to H4 did NOT rescue BRC.',NULL,'2d5d5b7','agent','2026-06-17 15:41:06',NULL);
INSERT INTO log_strategy (log_id,idea_id,event,component,from_value,to_value,verdict,rationale,result_id,git_sha,decided_by,created_at,params_json) VALUES (54,'BRC-001','ADOPTED','filter','all raw confirmed zones (emitter over-counts overlaps the live EA drops)','Option-A overlap consolidation: new zone dedups vs currently-ALIVE same-TF/same-dir set, >=50% overlap -> keep bigger (L1..L2 range), smaller flagged is_primary=0 + consolidated_into={survivor zone_key}. Traded set = is_primary=1.','ADOPTED','Live-EA (CCircularBuffer::ConsolidateOverlappingZones) fidelity. Full-IS re-emit run_id=5: 100,034 zones, byte-identical existing cols vs run 3 (0 diffs), 31.2% consolidated (68,798 primary). IS ledger FROZEN = run_id=5.',NULL,'a934dbe','human','2026-06-19 16:11:03',NULL);
