INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (112,'BRC-001','done','BRC zones.py Path B rewrite: consume struct.rawbreakout stream -> pair same-direction breaks (1st breaks P2=L1, 2nd breaks P5; P5 more extreme + older than P1) -> swings give P1(L2)+P3(gate RESTORED P3<P1) -> L1=P2,L2=P1,fifty=mid; label each zone same-bar vs sequential (H_alt-2 input). Trace P1/L2 source against EA first_barrier/L2_price.','','variant','P1','2026-06-17 08:06:33','2026-06-17 08:28:40','2026-06-17 08:28:40','zones.py rewritten Path B: consumes struct.rawbreakout stream; swing-seeded P1/P2/P3/P5; confirmation = the two same-direction breaks (P2 break=L1 entry, P5 break=P4); same_bar/sequential label added (H_alt-2 input). P3<P1 gate RESTORED (deliberate EA departure). L1=P2,L2=extreme(P1,P3)==P1,fifty=mid; traced vs EA CreateZoneFrom5Pointer first_barrier/swing_between. D1 w=3: 652 zones (sell296/buy356, same_bar227/seq425), all pass invariants (L2==P1, P5 older than P1, geometry, 1st-break<=2nd).');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (113,'BRC-001','done','BRC accuracy fixes (port from EA B2BDetector): freshness (no swing between P3 and P4), gap-validation (L2 not closed-through before P4), one-zone-per-P5 dedup keeping freshest P1. Fixes stale/duplicate zones flagged as inaccurate; needed regardless of detection method.','','variant','P1','2026-06-17 08:06:33','2026-06-17 08:47:33','2026-06-17 08:47:33','Ported 3 EA accuracy gates into zones.py: (1) no-interruption freshness (reject if any swing between P3 and P4, B2BDetector.mqh:635-645), (2) gap-validation (reject if L2 closed-through before P4, mqh:647-659), (3) one-zone-per-P5 dedup keeping freshest P1 (PASS 2, mqh:772-804). D1 w=3: 652->245 zones (-62%). Spurious cross-structure bridge zone (old Dec P1->Jan04 P4) KILLED; surviving Jan-04 BUY zone now has P3=01-03 immediately before P4=01-04 (fresh local). All 245 pass geometry invariants. STILL deferred: full swing-reuse exclusivity (EA PASS 3), retest (task 108). visual.py overview title updated.');
