INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (115,'BRC-001','done','BRC Gate-2 sanity render: 1-2yr D1, buys/sells/both separately','Before passing Gate 2: render full 1-2 years of D1 Path-B zones as THREE separate overviews for eyeball sanity — (1) BUY zones only, (2) SELL zones only, (3) both combined. Needs a direction filter on visual.plot_overview (buy/sell/both) + a longer bar window (~500 D1 bars ~= 2yr). Syafiq eyeballs all three -> THEN pipeline.open_gate(BRC-001,2)+pass_gate(2). Gate 2 pass is BLOCKED on this. Open P5-max-age refinement still optional (zone_16 had a ~2mo-old P5 barrier, faithful to EA, deferred unless Syafiq wants a nearby-barrier rule).','cleanup','P1','2026-06-17 08:54:24','2026-06-17 14:01:50','2026-06-17 14:01:50','DONE: visual.plot_overview direction filter (buy/sell/both) + overview3 batch + 500-bar default; 3 PNGs rendered + Syafiq eyeballed; Gate 2 PASSED. commit 118afbb.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (116,'BRC-001','done','BRC zone lifecycle: post-confirmation invalidation (close beyond L2=P1)','Forward-walk each CONFIRMED zone from P4. Mark DEAD (is_invalidated + invalidation_time) at the FIRST bar whose CLOSE is beyond L2(=P1): close>L2 SELL / close<L2 BUY. Close-based, mirrors EA B2BZoneStatus.mqh:169-197. Death boundary: ALL touch/continuation measurement runs only on the pre-invalidation segment. Currently MISSING (zones.py has only PRE-confirmation _passes_gap). Prereq for task 108. Distinct from T3: T3=wick poke of L2 (alive); invalidation=CLOSE beyond L2.','infra','P1','2026-06-17 13:40:48','2026-06-17 14:09:59','2026-06-17 14:09:59','Built lifecycle.py: zone_life()/label_lifecycles() forward-walk each confirmed zone from P4-exclusive, mark DEAD at first bar CLOSING beyond L2 (close>max(L1,L2) SELL / close<min(L1,L2) BUY) — mirrors EA B2BZoneStatus.mqh:169-197. D1 full history: 245 zones, 196 invalidated, 49 alive, median 20 bars to death. First-death invariant verified (0 violations / 196).');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (117,'BRC-001','done','BRC per-zone lifecycle visual panel (Python analog of MT5 live-watch)','AFTER tasks 116+108 land. Extend visual.plot_zone into a per-zone LIFECYCLE panel: zone box + forward bars with T1/T2/T3 touch markers (where each fires) + invalidation bar (where it dies). Frozen, reproducible replay = research analog of MT5 watching zones detected/removed live. DECISION 2026-06-17: do NOT rebuild MT5 state-event engine in Python (batch is correct for research); live-watch belongs at deployment via Gate-7 Python<->MT5 fidelity. Optional later: frame-by-frame animation (deferred, low value).','cleanup','P2','2026-06-17 13:47:10','2026-06-19 15:15:43','2026-06-19 15:15:43','DROPPED — not needed. Live per-zone lifecycle panel is the MQL5 brc_visual.mqh chart layer (task 121); no Python analog required since BRC runs natively in MT5.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (118,'BRC-001','done','BRC MT5 zone-emitter EA: fresh build in brc_system namespace — detect 5-point zone (all 9 TFs M5..MN1 via CopyRates on one M5 run), track retest ladder T1/T2/T3 + continuation/invalidation, write one lifecycle row per zone per TF to UTF-8 CSV. Open-prices-only tester model (close-only detection). Old B2BDetector = read-only reference; fidelity-diff vs live Sigma EA.','','port','P1','2026-06-17 17:28:16','2026-06-19 15:15:43','2026-06-19 15:15:43','BRC emitter EA fully built+validated: compiles clean, 5-pt detection all TFs, lifecycle CSV, byte-identical parity (sha e1ed5c3c), 8.5yr emitted (100034 zones) + ingested. Sub-tasks 119-125,128 all done.');
