INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (121,'BRC-001','done','BRC chart visualizer brc_visual.mqh','MT5 chart visualizer (mirrors orb Visualizer.mqh): swings (arrows at pivots), raw breakouts (markers on break bar), BRC zones (L1<->L2 rect + mid dashed line, colored by direction, T1/T2/T3 retest dots + invalidation marker). Sanity-check for swings/breakouts/zones. Needs tester Visual Mode (NOT Open-prices-only). Distinct from task 117 (Python panel).','port','P2','2026-06-17 18:23:49','2026-06-18 10:46:06','2026-06-18 10:46:06','brc_visual.mqh built, wired, compiles 0/0, live-tick touch works. Inputs curated: colours + bullet/label font sizes -> const (hidden); swings/breaks/P1-P5/dead-zones default OFF.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (122,'BRC-001','done','Match BRC zones to Sigma B2B zones (detection + drawing parity)','BRC zones look wrong vs live Sigma B2B. Next agent MUST read all 5 Sigma detection modules before touching brc_zones.mqh/brc_visual.mqh: (1) Include/Sigma_System/V5.0/Detection/B2BDetector.mqh (DetectB2B_5Pointer 2-pass candidate+winner-per-P5, CreateZoneFrom5Pointer, FindP5_OlderBarrier, IsSwingUsedInZones exclusivity); (2) B2BZoneManager.mqh (GenerateZoneId FNV-1a, ConsolidateOverlappingZones 50pct, RemoveInvalidated/Dead, GenerateZoneId); (3) B2BZoneStatus.mqh (T1->T2->T3 ORDERED gating: 50pct only after L1, L2 only after 50pct; close-only invalidation on bar-close; ValidateZoneAgainstHistory); (4) B2BConfluence.mqh (russian-doll parent overlap, TF rank, pioneer ATH/ATL); (5) B2BTradeTracker.mqh (trade lifecycle MAE/MFE). Key divergences already spotted vs brc_zones.mqh: B2B P2=FIRST low after P1, BRC P2=LAST low before P3; B2B P3=FIRST high after P2 + strict no-swing-between-P3-and-P4 REJECT, BRC P3=last-swing-before-P4 (reconstructs fresher instead of rejecting); B2B does winner-per-P5 + IsSwingUsedInZones exclusivity + overlap consolidation that BRC lacks; B2B retest ladder is ORDER-GATED (BRC retest also gated, verify). Verdict so far: detection is spec-faithful except the DELIBERATE backward-freshness oracle delta. Confirm whether thats the visible wrong, or align P2/P3 selection + add exclusivity/consolidation. Also compare DRAWING (Sigma DrawB2BZone in Visualizer.mqh: L1/L2 dashed RAY + 50pct dot + left vertical + L2 label with [Tn]) which brc_visual.mqh already mirrors.','port','P1','2026-06-18 07:54:33','2026-06-18 10:46:06','2026-06-18 10:46:06','Detection parity (forward-scan port, a1ccce0) + drawing parity (Syafiq confirmed levels match) + touch parity (death-bar 9638ed2 + instant per-tick this session) all landed. ConsolidateOverlappingZones split to own deferred task.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (123,'BRC-001','done','BRC instant per-tick T-touch (live-chart [Tn] lag fix)','OnTick now runs a live intrabar touch pass (BrcLiveTouch) off each TF forming bar so [Tn] flips the instant price wicks a level. Mirrors B2B per-tick touch (touches=tick, invalidation/continuation stay close-only). Data-neutral for CSV: touch lands on same bar either way.','port','P1','2026-06-18 10:46:06','2026-06-18 10:46:06','2026-06-18 10:46:06','Done + pushed (master). Compiles 0/0. Was the open P1 bug from 2026-06-18 Afternoon handover.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (124,'BRC-001','done','BRC smoke run: 1yr IS slice end-to-end (emit -> task119 ingest -> verify rows)','Run brc_baysix in MT5 tester on Dukascopy-backed symbol over a 1yr IS year (e.g. 2022/2023, NOT the OOS window). Validate CSV schema + run task-119 ingest into research.db tester_zones + confirm row count/schema. Green-light gate before the full run. Confirm tester points at Dukascopy custom symbol, not JM live XAUUSD (shallow M5).','data','P1','2026-06-18 10:46:06','2026-06-18 11:21:16','2026-06-18 11:21:16','Smoke 1yr IS (2024, M5 dukascopy, open_only model, 23s run): emit->ingest->verify GREEN. run #2, 12489 zones, per-TF matches CSV (M5=7791..MN1=1), all zones resolved (610 alive + 11879 invalidated), continued ~50%, L1-touched ~98%.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (125,'BRC-001','done','BRC full IS emit run 2016-01 -> 2024-06 (all 8 TFs, single M5-base run)','After smoke green-light. One M5-base run emits all 8 TFs (CopyRates) to one CSV with tf column. IS-only by design (physical OOS lockout). Open-prices-only model (close-only detection). Dukascopy symbol.','data','P1','2026-06-18 10:46:06','2026-06-18 12:22:20','2026-06-18 12:22:20','Full IS emit ingested: run #3, 100034 zones, M5 confirm 2016-06-13->2024-06-28 (stops before OOS). Per-TF M5=61434,M15=21091,M30=10574,H1=5289,H4=1359,D1=240,W1=38,MN1=9. All resolved (1392 alive + 98642 invalidated), continued ~51%, L1-touched ~99.5%. NOTE: data starts 2016-06 not 2016-01 (Dukascopy M5 depth). Run was slow (~hrs) -> perf task 128.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (126,'BRC-001','open','BRC OOS confirmation emit 2024-07 -> 2026-06 (BLOCKED until IS config frozen)','Physical OOS lockout: do NOT run until IS funnel config frozen (strategy_log.get_live_config(BRC-001) non-empty; is_discipline_guards enforces). Recent monster-vol regime = deployment regime. Separate confirmation pass.','data','P2','2026-06-18 10:46:06','2026-06-18 10:46:06',NULL,NULL);
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (127,'BRC-001','done','BRC ConsolidateOverlappingZones decision (50pct-overlap dedup, last B2B dedup BRC lacks)','Deferred from task 122. B2BZoneManager.mqh:230 keeps biggest of 50pct-overlapping zones. NOT ported because it DELETES zones, thinning the task-120 funnel dataset. Decide: add for strict 1:1, OR treat as downstream Python filter and keep all zones in the ledger.','variant','P2','2026-06-18 10:46:06','2026-06-19 16:11:03','2026-06-19 16:11:03','DONE — 6-file additive build, 0err/0warn, parity PASS byte-identical on 2024 1yr (run4 vs run2) AND full 8.5yr IS (run5 vs run3, 0 diffs). All 100,034 zone_keys unique. IS frozen = run_id=5 (strategy_log 54). 31.2% consolidated.');
INSERT INTO log_tasks (task_id,idea_id,status,title,detail,kind,priority,created_at,updated_at,resolved_at,resolution) VALUES (128,'BRC-001','done','BRC emitter O(n^2) close-bar pipeline optimization (8.5yr IS = hours, climbing ETA; 1yr=23s)','Unbounded full-array scans every bar (InpMaxAge=0 = no prune): (1) BrcDetectBreaksOnBar scans ALL swings/bar [dominant]; (2) step-4 advance loops ALL zones/bar not just alive; (3) BrcTryConfirmZone freshness+dedup full-scan swings/zones per break. FIX (parity-safe; verify vs 1yr smoke run#2 = 12489 zones, per-TF M5=7791..MN1=1): alive-zone-only iteration + bounded swing-lookback prune + bounded dedup. CHECK FIRST: does live Sigma B2B EA cap swing/zone lookback -> mirror it 1:1. See brc_breakouts.mqh L36, brc_zones.mqh L188/L251, brc_baysix.mq5 L149.','variant','P2','2026-06-18 12:21:30','2026-06-19 15:09:10','2026-06-19 15:09:10','Pruned BRC emitter O(n^2): live_sw/alive_idx free-lists (order-preserving compaction) + binary-search BrcFirstSwingAfter/BrcFindP5ForP1 + O(1) freshness pre-bound. 8.5yr IS emit hours->9m30s. PARITY: 2024 1yr rerun byte-identical to original (12489 zones, sha e1ed5c3c). 8.5yr=100034 zones. call_id 80.');
